package main

import("crypto/sha256";"encoding/csv";"encoding/hex";"encoding/json";"io";"net/http";"sort";"strings";"time";"go.mau.fi/whatsmeow/types")
func ensureBulkMessageTable()error{_,e:=userDB.Exec(`CREATE TABLE IF NOT EXISTS public.bulk_messages(id BIGSERIAL PRIMARY KEY,user_id TEXT,target TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,assigned_sender TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),sent_at TIMESTAMPTZ,campaign_id TEXT,dedupe_key TEXT); ALTER TABLE public.bulk_messages ADD COLUMN IF NOT EXISTS assigned_sender TEXT; ALTER TABLE public.bulk_messages ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT now(); ALTER TABLE public.bulk_messages ADD COLUMN IF NOT EXISTS campaign_id TEXT; ALTER TABLE public.bulk_messages ADD COLUMN IF NOT EXISTS dedupe_key TEXT; ALTER TABLE public.bulk_messages ALTER COLUMN user_id DROP NOT NULL; CREATE INDEX IF NOT EXISTS bulk_messages_queue_idx ON public.bulk_messages(status,id); CREATE UNIQUE INDEX IF NOT EXISTS bulk_messages_dedupe_idx ON public.bulk_messages(dedupe_key) WHERE dedupe_key IS NOT NULL`);return e}
func bulkConnectedDevices()[]string{manager.mu.RLock();defer manager.mu.RUnlock();ids:=[]string{};for id,s:=range manager.sessions{if s!=nil&&s.client!=nil&&s.client.IsLoggedIn()&&s.client.IsConnected(){ids=append(ids,id)}};sort.Strings(ids);return ids}
func normalizeBulkPhone(v string)(string,bool){v=strings.NewReplacer("+",""," ","","-","").Replace(strings.TrimSpace(v));if len(v)<7||len(v)>15{return "",false};for _,c:=range v{if c<'0'||c>'9'{return "",false}};return v,true}
func bulkKey(c,p,m string)string{h:=sha256.Sum256([]byte(c+"\x00"+p+"\x00"+m));return hex.EncodeToString(h[:])}
func bulkQueuedCount()int{var n int;_=userDB.QueryRow(`SELECT count(*) FROM public.bulk_messages WHERE user_id IS NULL AND status='queued'`).Scan(&n);return n}
func claimBulkRow(uid string)(int64,string,string,bool){tx,e:=userDB.Begin();if e!=nil{return 0,"","",false};defer tx.Rollback();var id int64;var target,text string;if e=tx.QueryRow(`SELECT id,target,message FROM public.bulk_messages WHERE user_id IS NULL AND status='queued' ORDER BY id FOR UPDATE SKIP LOCKED LIMIT 1`).Scan(&id,&target,&text);e!=nil{return 0,"","",false};if _,e=tx.Exec(`UPDATE public.bulk_messages SET status='sending',attempts=attempts+1,assigned_sender=$1,updated_at=now() WHERE id=$2`,uid,id);e!=nil{return 0,"","",false};if e=tx.Commit();e!=nil{return 0,"","",false};return id,target,text,true}
func markBulkFailed(id int64,msg string){_,_=userDB.Exec(`UPDATE public.bulk_messages SET status='failed',last_error=$1,updated_at=now() WHERE id=$2`,msg,id)}
func markBulkSent(id int64){_,_=userDB.Exec(`UPDATE public.bulk_messages SET status='sent',sent_at=now(),last_error=NULL,updated_at=now() WHERE id=$1`,id)}
func nextBulkSender(ids []string)string{if len(ids)==0{return ""};var n uint64;for _,s:=range ids{for _,b:=range []byte(s){n=n*131+uint64(b)}};return ids[n%uint64(len(ids))]}
func processBulkMessagesGlobal(){if getAdminSetting("bulk_auto_send_enabled","false")!="true"{return};ids:=bulkConnectedDevices();if len(ids)==0{return};limit:=safeSettingInt("bulk_batch_size",5,1,20);for i:=0;i<limit;i++{uid:=nextBulkSender(ids);id,target,text,ok:=claimBulkRow(uid);if !ok{return};s:=getSession(uid);if s==nil||s.client==nil{markBulkFailed(id,"WhatsApp account disconnected");continue};s.mu.Lock();e:=safeSendMessage(uid,s.client,types.JID{User:target,Server:types.DefaultUserServer},text);s.mu.Unlock();if e!=nil{markBulkFailed(id,e.Error())}else{markBulkSent(id)}}}
func bulkWorkerLoop(){for userDB==nil{time.Sleep(2*time.Second)};_=ensureBulkMessageTable();for{processBulkMessagesGlobal();time.Sleep(10*time.Second)}}
func bulkMessageStatusHandler(w http.ResponseWriter,r *http.Request){enableCORS(w);w.Header().Set("Content-Type","application/json");if r.Method!=http.MethodGet{w.WriteHeader(405);return};if e:=ensureBulkMessageTable();e!=nil{w.WriteHeader(500);return};_,_=userDB.Exec(`UPDATE public.bulk_messages SET status='queued',assigned_sender=NULL,last_error='Recovered after worker timeout',updated_at=now() WHERE user_id IS NULL AND status='sending' AND updated_at < now()-interval '15 minutes'`);out:=map[string]any{"status":"success"};for _,st:=range []string{"queued","sending","sent","failed","paused","cancelled"}{var n int;_=userDB.QueryRow(`SELECT count(*) FROM public.bulk_messages WHERE user_id IS NULL AND status=$1`,st).Scan(&n);out[st]=n};devices:=[]DeviceInfo{};for _,uid:=range bulkConnectedDevices(){s:=getSession(uid);if s!=nil&&s.client!=nil&&s.client.Store!=nil&&s.client.Store.ID!=nil{devices=append(devices,DeviceInfo{UserID:uid,Phone:s.client.Store.ID.User,Connected:true,LoggedIn:true,State:"ready"})}};out["connected_accounts"]=len(devices);out["devices"]=devices;_=json.NewEncoder(w).Encode(out)}
func bulkMessageImportHandler(w http.ResponseWriter,r *http.Request){enableCORS(w);w.Header().Set("Content-Type","application/json");if r.Method!=http.MethodPost{w.WriteHeader(405);return};if e:=ensureBulkMessageTable();e!=nil{w.WriteHeader(500);return};if strings.HasPrefix(r.Header.Get("Content-Type"),"application/json"){var in struct{Action string `json:"action"`;UserIDs []string `json:"user_ids"`;Limit int `json:"limit"`};if e:=json.NewDecoder(r.Body).Decode(&in);e!=nil{w.WriteHeader(400);return};a:=strings.ToLower(strings.TrimSpace(in.Action));if a!="send"{q:=map[string]string{"pause":"UPDATE public.bulk_messages SET status='paused',updated_at=now() WHERE user_id IS NULL AND status='queued'","resume":"UPDATE public.bulk_messages SET status='queued',updated_at=now() WHERE user_id IS NULL AND status='paused'","cancel":"UPDATE public.bulk_messages SET status='cancelled',updated_at=now() WHERE user_id IS NULL AND status IN ('queued','paused','failed')","retry_failed":"UPDATE public.bulk_messages SET status='queued',attempts=0,last_error=NULL,assigned_sender=NULL,updated_at=now() WHERE user_id IS NULL AND status='failed'","clear_queue":"DELETE FROM public.bulk_messages WHERE user_id IS NULL AND status IN ('queued','paused','cancelled','failed')"};sql,ok:=q[a];if !ok{_=json.NewEncoder(w).Encode(APIResponse{Status:"error",Message:"Unknown action"});return};res,e:=userDB.Exec(sql);if e!=nil{_=json.NewEncoder(w).Encode(APIResponse{Status:"error",Message:e.Error()});return};n,_:=res.RowsAffected();_=json.NewEncoder(w).Encode(map[string]any{"status":"success","action":a,"affected":n});return};limit:=in.Limit;if limit<1{limit=20};if limit>200{limit=200};ids:=in.UserIDs;if len(ids)==0{ids=bulkConnectedDevices()};sent,attempted:=0,0;for attempted<limit&&len(ids)>0{uid:=nextBulkSender(ids);id,target,text,ok:=claimBulkRow(uid);if !ok{break};attempted++;s:=getSession(uid);if s==nil||s.client==nil{markBulkFailed(id,"WhatsApp account disconnected");continue};s.mu.Lock();e:=safeSendMessage(uid,s.client,types.JID{User:target,Server:types.DefaultUserServer},text);s.mu.Unlock();if e!=nil{markBulkFailed(id,e.Error())}else{markBulkSent(id);sent++}};_=json.NewEncoder(w).Encode(map[string]any{"status":"success","attempted":attempted,"sent":sent,"remaining_queue":bulkQueuedCount()});return};r.Body=http.MaxBytesReader(w,r.Body,512<<20);mr,e:=r.MultipartReader();if e!=nil{w.WriteHeader(400);return};var file io.Reader;for{p,x:=mr.NextPart();if x==io.EOF{break};if x!=nil{w.WriteHeader(400);return};if p.FormName()=="file"{file=p;break}};if file==nil{w.WriteHeader(400);return};reader:=csv.NewReader(file);reader.FieldsPerRecord=-1;campaign:=time.Now().UTC().Format("20060102T150405.000000000Z");tx,e:=userDB.Begin();if e!=nil{w.WriteHeader(500);return};defer tx.Rollback();imported,skipped:=0,0;first:=true;for{rec,x:=reader.Read();if x==io.EOF{break};if x!=nil{skipped++;continue};if first{first=false;if len(rec)>0&&strings.EqualFold(strings.TrimSpace(rec[0]),"phone"){continue}};if len(rec)<3{skipped++;continue};phone,ok:=normalizeBulkPhone(rec[0]);msg:=strings.TrimSpace(rec[1]);cons:=strings.ToLower(strings.TrimSpace(rec[2]));if !ok||msg==""||len(msg)>10000||(cons!="yes"&&cons!="true"&&cons!="1"){skipped++;continue};key:=bulkKey(campaign,phone,msg);res,x:=tx.Exec(`INSERT INTO public.bulk_messages(user_id,target,message,status,campaign_id,dedupe_key,updated_at) VALUES(NULL,$1,$2,'queued',$3,$4,now()) ON CONFLICT(dedupe_key) DO NOTHING`,phone,msg,campaign,key);if x!=nil{skipped++;continue};n,_:=res.RowsAffected();if n==0{skipped++;continue};imported++};if e=tx.Commit();e!=nil{w.WriteHeader(500);return};_=json.NewEncoder(w).Encode(map[string]any{"status":"success","campaign_id":campaign,"imported":imported,"skipped":skipped})}
func init(){go bulkWorkerLoop()}
func bulkAdminPageHandler(w http.ResponseWriter,r *http.Request){if r.Method!=http.MethodGet{w.WriteHeader(405);return};w.Header().Set("Content-Type","text/html; charset=utf-8");_,_=w.Write([]byte(`<!doctype html><html><body><h1>Bulk Messages</h1><input id="f" type="file" accept=".csv"><button onclick="u()">Import CSV</button><button onclick="a('pause')">Pause</button><button onclick="a('resume')">Resume</button><button onclick="a('retry_failed')">Retry Failed</button><button onclick="a('cancel')">Cancel</button><button onclick="a('clear_queue')">Clear Queue</button><button onclick="s()">Send Selected</button><pre id="o"></pre><script>const H={'X-Admin-Token':sessionStorage.getItem('admin_token')||''};async function api(u,o={}){o.headers=Object.assign({},H,o.headers||{});return(await fetch(u,o)).json()}async function u(){let f=document.getElementById('f').files[0],x=new FormData();if(!f)return;x.append('file',f);o.textContent=JSON.stringify(await api('/admin/bulk/import',{method:'POST',body:x}),null,2)}async function a(x){o.textContent=JSON.stringify(await api('/admin/bulk/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:x})}),null,2)}async function s(){o.textContent=JSON.stringify(await api('/admin/bulk/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'send',limit:200})}),null,2)}</script></body></html>`))}
